INSERT INTO `tmp_548_creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(3063,0,0,'Hulfnar! Thontek! Stand and address me.',12,3,100,1,0,0,'Krang Stonehoof'),
(3063,1,0,'I want you both to demonstrate the techniques I have taught you for the benefit of the younger students here. Ready... begin!',12,3,100,1,0,0,'Krang Stonehoof'),
(3063,2,0,'Enough talk you two! Commence fighting!',12,3,100,22,0,0,'Krang Stonehoof'),
(3063,3,0,'Now that\'s a War Stomp! Good job!',12,3,100,21,0,0,'Krang Stonehoof'),
(3063,3,1,'That\'s how it\'s done class! You better be paying attention!',12,3,100,21,0,0,'Krang Stonehoof'),
(3063,3,2,'Now that\'s putting your hoof down!',12,3,100,21,0,0,'Krang Stonehoof'),
(3063,4,0,'Ish nu! That\'s enough!',12,3,100,1,0,0,'Krang Stonehoof'),
(3063,5,0,'Well Done!',12,3,100,1,0,6575,'Krang Stonehoof'),
(3063,6,0,'Good, good. Now bow to each other.',12,3,100,1,0,0,'Krang Stonehoof'),
(3063,7,0,'Now bow to me.',12,3,100,1,0,0,'Krang Stonehoof'),
(3063,8,0,'Good job you two. Now go have a seat.',12,3,100,1,0,0,'Krang Stonehoof'),
(3277,0,0,'My talons will shred your puny body, $R.',12,0,100,0,0,0,'Witchwing Roguefeather'),
(3287,0,0,'Go swiftly, $n. My fate is in your hands.',12,1,100,0,0,0,'Hana zua'),
(3925,0,0,'%s goes into a rage after seeing a friend fall in battle!',16,0,100,0,0,0,'Thistlefur Avenger'),
(4500,0,0,'Puny $r wanna fight Overlord Mok\'Morokk? Me beat you! Me boss here!',12,0,100,0,0,0,'Overlord Mok\'Morokk'),
(4500,1,0,'I\'ll crush you!',12,0,100,0,0,0,'Overlord Mok\'Morokk'),
(4500,2,0,'Me scared! Me run now!',14,0,100,0,0,0,'Overlord Mok\'Morokk'),
(4670,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Hatefury Rogue'),
(4671,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Hatefury Trickster'),
(4672,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Hatefury Felsworn'),
(4673,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Hatefury Betrayer'),
(4674,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Hatefury Shadowstalker'),
(4675,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Hatefury Hellcaller'),
(4721,0,0,'The Earth Mother watch over us; under cover of the night as in the day. Let this fire illuminate both our bodies and spirits and remind us of our honored ancestors, who are ever present and guiding our way.\n',12,3,100,1,0,0,'Zangen Stonehoof'),
(4968,0,0,'Perhaps I should explain...',12,0,100,1,0,0,'Lady Jaina Proudmoore'),
(4968,1,0,'I had arranged for a secret summit between Warchief Thrall and King Wrynn, here in Theramore.',12,0,100,1,0,33093,'Lady Jaina Proudmoore'),
(4968,2,0,'The king was to travel here by ship, in secret. But the ship never arrived, and King Wrynn disappeared.',12,0,100,1,0,0,'Lady Jaina Proudmoore'),
(4968,3,0,'Your help enabled us to connect the Defias to the mastermind behind the abduction, Onyxia, who was posing as a member of the royal court.',12,0,100,1,0,0,'Lady Jaina Proudmoore'),
(4968,4,0,'Meanwhile, the king managed to escape his captors, and returned to Stormwind to deal with Onyxia.',12,0,100,1,0,0,'Lady Jaina Proudmoore'),
(4968,5,0,'I will send word that you have discovered the link to the Defias. I was a fool to think them broken with the defeat of Edwin Van Cleef, and King Wrynn will want to make an example of all who remain.',12,0,100,1,0,0,'Lady Jaina Proudmoore'),
(5089,0,0,'Alright! Alright! We surrender... Just put your weapons down, I\'ll cooperate!',12,7,100,0,0,0,'Balos Jacken'),
(5471,0,0,'%s is ready to be fed.',16,0,100,0,0,0,'Dunemaul Ogre'),
