(6513,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Un\'Goro Stomper'),
(6986,0,0,'I don\'t know what you\'re talking about, elf, and I don\'t appreciate you pokin\' around in my business!',12,0,100,1,0,0,''),
(6986,1,0,'I do seem to have mistakenly come into possesion of some artifacts from Uldum. Perhaps the Reliquary is interested in those?',12,0,100,1,0,0,''),
(6986,2,0,'Fine, fine. I may have helped him contact an interested buyer. But keep your voice down! You\'ll scare away my customers.',12,0,100,1,0,0,''),
(7157,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Deadwood Avenger'),
(8201,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Omgorn the Lost'),
(8761,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Mosshoof Courser'),
(8956,0,0,'%s goes into a frenzy!',16,0,100,0,0,0,'Angerclaw Bear'),
(8958,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Angerclaw Mauler'),
(9516,0,0,'Pathetic mortal... I will build a new empire atop your corpse!',14,0,100,0,0,0,'Lord Banehollow'),
(9516,1,0,'No... NO! This is my domain! You cannot have... it...',14,0,100,0,0,0,'Lord Banehollow'),
(10541,0,0,'Holy Krakle! The temperature is 428,000 degrees Kraklenheit! ',12,0,100,0,0,0,'Krakle\'s Thermometer'),
(10541,0,1,'It\'s 428,000 degrees Kraklenheit... What\'s happening, hot stuff!?',12,0,100,0,0,0,'Krakle\'s Thermometer'),
(10541,0,2,'DING! 428,000 degrees Kraklenheit, exactly! Well, approximately. Almost. Somewhere around there...',12,0,100,0,0,0,'Krakle\'s Thermometer'),
(10541,0,3,'Measuring by Kraklenheit, it is 428,000 degrees! That\'s Krakley!',12,0,100,0,0,0,'Krakle\'s Thermometer'),
(10541,1,0,'8536 degrees Kraklenheit is the reading... Tired of me yet?',12,0,100,0,0,0,'Krakle\'s Thermometer'),
(10541,2,0,'*sigh* ...113 degrees Kraklenheit. Can\'t you do any better?',12,0,100,0,0,0,'Krakle\'s Thermometer'),
(10541,3,0,'Wow, it\'s 3 degrees Kraklenheit. Keep looking.',12,0,100,0,0,0,'Krakle\'s Thermometer'),
(10541,4,0,'The temperature is 564 degrees Kraklenheit.',12,0,100,0,0,0,'Krakle\'s Thermometer'),
(10599,0,0,'Start running!',12,3,100,25,0,6280,'Hulfnar Stonetotem'),
(10599,1,0,'Bring it on!',12,3,100,22,0,6281,'Hulfnar Stonetotem'),
(10600,0,0,'Do not push me, or I will impale you on my horns!',12,3,100,22,0,6277,'Thontek Rumblehoof'),
