(33440,0,1,'You not gunna let me die, huh? Okay, then...',12,0,100,1,0,0,'Demoralized Peon'),
(33440,0,2,'You keep a lookout, $r! The elfs are everywhere!',12,0,100,1,0,0,'Demoralized Peon'),
